package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items
var WsEofFlag string = "N"                         // PIC X len=1 = "N"
var WsLabel string = strings.Repeat(" ", 20)      // PIC X(20) len=20 = SPACES
var WsACount int64 = 0                             // PIC 99 len=2 = 0
var WsTotalA int64 = 0                             // PIC 999 len=3 = 0
var WsCount int64 = 0                              // PIC 999 len=3 = 0

var curRec PartRec
var partData []PartRec
var partIndex int

func delimitedBySpace(s string) string {
	if i := strings.IndexByte(s, ' '); i >= 0 {
		return s[:i]
	}
	return s
}

func parseSerial(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	v, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return 0
	}
	return v
}

func openPartFile() {
	partData = nil
	partIndex = 0
	f, err := os.Open("input.dat")
	if err != nil {
		return
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	const maxCap = 10 * 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	sc.Buffer(buf, maxCap)
	for sc.Scan() {
		line := sc.Text()
		if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		rec := PartRec{
			LbPart:   line[0:8],
			LbRegion: line[8:11],
			LbSerial: parseSerial(line[11:15]),
		}
		partData = append(partData, rec)
	}
}

func MainPara() {
	openPartFile()
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	SummaryPara()
}

func ReadPara() {
	if partIndex < len(partData) {
		curRec = partData[partIndex]
		partIndex++
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	WsACount = int64(strings.Count(curRec.LbPart, "A")) % 100

	regionPart := delimitedBySpace(curRec.LbRegion)
	partPart := delimitedBySpace(curRec.LbPart)
	serialMod := curRec.LbSerial % 10000
	if serialMod < 0 {
		serialMod += 10000
	}
	serialStr := fmt.Sprintf("%04d", serialMod)
	joined := regionPart + "-" + partPart + "-" + serialStr
	if len(joined) > 20 {
		WsLabel = joined[:20]
	} else {
		WsLabel = joined + strings.Repeat(" ", 20-len(joined))
	}
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")
	WsTotalA = (WsTotalA + WsACount) % 1000
	WsCount = (WsCount + 1) % 1000
	countStr := fmt.Sprintf("%02d", WsACount)
	os.Stdout.WriteString(WsLabel + " A=" + countStr + "\n")
	ReadPara()
}

func SummaryPara() {
	cStr := fmt.Sprintf("%03d", WsCount)
	tStr := fmt.Sprintf("%03d", WsTotalA)
	os.Stdout.WriteString("LABELS: " + cStr + " A-TOTAL: " + tStr + "\n")
}

func main() {
	MainPara()
}
